static z_t7986_t z_t60_stripPrefix(
    const z_t60_t* self, const z_t60_t* p) {
    z_t7986_t out = {0};
    if (p->size > self->size
        || (p->size > 0 && memcmp(self->data, p->data, p->size) != 0)) {
        out.tag = Z_T7986_TAG_0;
        return out;
    }
    z_t60_t* boxed = (z_t60_t*)z_xmalloc(sizeof(z_t60_t));
    boxed->data = self->data + p->size;
    boxed->size = self->size - p->size;
    out.tag = Z_T7986_TAG_1;
    out.data = boxed;
    return out;
}


