static const z_t6356_t _zag1681 = { { .data = "chan_grow", .size = 9 }, { .length = 1, .data = _zag1679 }, { .length = 2, .data = _zag1680 }, { .data = "/* the ring, twice as large, its values in order from the start; the lock is\n   held */\nstatic void z_chan_grow(z_chan* b) {\n    uint64_t n = b->size * 2;\n    unsigned char* r = (unsigned char*)z_xmalloc(b->elemSize * n);\n    for (uint64_t i = 0; i < b->len; i++) {\n        memcpy(r + i * b->elemSize, b->ring + ((b->head + i) % b->size) * b->elemSize, b->elemSize);\n    }\n    free(b->ring);\n    b->ring = r;\n    b->size = n;\n    b->head = 0;\n}", .size = 444 } };
