static const z_t6541_t _zag3234 = { { .data = "", .size = 0 }, { .data = "", .size = 0 }, { .length = 0, .data = NULL }, { .data = "/* Barrier -- where a fixed number of threads wait for each other (sync.z).\n   One lock and one condition variable in a heap block every handle shares:\n   each round counts its arrivals, the last one starts the next round and\n   wakes the rest, and a waiter waits until the round it arrived in has ended. */\ntypedef struct z_@@NAME@@_blk {\n    z_mutex_t m;\n    z_cond_t c;\n    uint64_t count;\n    uint64_t waiting;\n    uint64_t round;\n    Z_ATOMIC(uint64_t) refs;\n} z_@@NAME@@_blk;\n\ntypedef struct z_@@NAME@@_t {\n    z_@@NAME@@_blk* b;\n} z_@@NAME@@_t;\n", .size = 552 } };
